package cl.bolsillo.app;
import org.json.*;import java.util.*;import java.time.*;
public class CatalogChartsTest {
 static int checks;static void yes(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 static JSONObject tx(String id,String type,long value,String date,String category,String account)throws Exception{return new JSONObject().put("id",id).put("type",type).put("amount",value).put("date",date).put("category",category).put("account",account).put("status","posted");}
 public static void main(String[] args)throws Exception{
  JSONObject d=Ledger.initial();JSONObject gift=new JSONObject().put("id","my-gift").put("name","  REGALO ").put("type","expense").put("archived",true).put("budget",123456789);d.getJSONArray("categories").put(gift);String categoryBefore=gift.toString(),accounts=d.getJSONArray("accounts").toString();d.getJSONArray("transactions").put(tx("kept","expense",9990,Ledger.today(),"my-gift","bank-mach"));String transactions=d.getJSONArray("transactions").toString();CategoryCatalog.migrate(d);
  yes(d.getJSONArray("transactions").toString().equals(transactions),"existing movements preserved exactly");yes(d.getJSONArray("accounts").toString().equals(accounts),"account balances and settings preserved exactly");yes(gift.toString().equals(categoryBefore),"personal category ID/name/archive/budget preserved");int matches=0;for(int i=0;i<d.getJSONArray("categories").length();i++){JSONObject c=d.getJSONArray("categories").getJSONObject(i);if(c.optString("type").equals("expense")&&CategoryCatalog.normalized(c.optString("name")).startsWith("regalo"))matches++;}yes(matches==1,"singular personal gift reused without duplicate");String migrated=d.toString();CategoryCatalog.migrate(d);yes(migrated.equals(d.toString()),"migration idempotent");
  for(String name:new String[]{"regalo","Regalos","RÉGALOS","  regalo  "}){JSONObject sample=Ledger.initial();sample.getJSONArray("categories").put(new JSONObject().put("id","custom").put("name",name).put("type","expense"));CategoryCatalog.migrate(sample);yes(Ledger.find(sample.getJSONArray("categories"),"expense-catalog-gifts")==null,"equivalent gift reused "+name);}
  JSONObject initial=Ledger.initial();CategoryCatalog.migrate(initial);yes(Ledger.find(initial.getJSONArray("categories"),"income-2")!=null&&Ledger.find(initial.getJSONArray("categories"),"expense-catalog-gifts")!=null,"income gifts and expense gifts remain distinct");
  JSONObject full=Ledger.initial();while(full.getJSONArray("categories").length()<300){int i=full.getJSONArray("categories").length();full.getJSONArray("categories").put(new JSONObject().put("id","custom-"+i).put("type","expense").put("name","Custom "+i));}CategoryCatalog.migrate(full);yes(full.getJSONArray("categories").length()==300,"catalog respects category limit");
  JSONObject chart=Ledger.initial();JSONArray ts=chart.getJSONArray("transactions");String today=Ledger.today(),old=LocalDate.parse(today).withDayOfMonth(1).minusMonths(1).toString();ts.put(tx("current","expense",1000000000000L,today,"expense-0","bank-mach"));ts.put(tx("other","expense",500000000000L,today,"expense-1","bank-bancoestado"));ts.put(tx("previous","expense",1000,old,"expense-0","bank-mach"));ts.put(tx("future","expense",999999,"2099-01-01","expense-0","bank-mach"));ts.put(tx("pending","expense",888888,today,"expense-0","bank-mach").put("status","pending"));ts.put(tx("excluded","expense",777777,today,"expense-0","bank-mach").put("excluded",true));ts.put(tx("income","income",666666,today,"income-0","bank-mach"));ts.put(tx("transfer","transfer",555555,today,"","bank-mach"));
  List<SpendingCharts.Slice> month=SpendingCharts.slices(chart,0),quarter=SpendingCharts.slices(chart,1),byAccount=SpendingCharts.slices(chart,2);yes(month.size()==2&&month.get(0).value==1000000000000L,"current month excludes pending/future/transfers/income");yes(quarter.get(0).value==1000000001000L,"rolling three calendar months include prior month");yes(byAccount.size()==2&&byAccount.get(0).id.equals("bank-mach")&&byAccount.get(0).value==1000000000000L,"account chart counts spending once with large CLP amounts");
  for(int i=2;i<8;i++)ts.put(tx("category-"+i,"expense",i*10000,today,"expense-"+i,"bank-mach"));List<SpendingCharts.Slice> grouped=SpendingCharts.slices(chart,0);long sum=0,expected=Ledger.flow(chart,today.substring(0,7),"expense","");for(SpendingCharts.Slice slice:grouped)sum+=slice.value;yes(grouped.size()==5&&grouped.get(4).id.isEmpty(),"long legend groups remainder");yes(sum==expected,"grouped shares preserve all exact money");yes(SpendingCharts.slices(Ledger.initial(),0).isEmpty(),"empty chart has no invented data");
  System.out.println("PASS: "+checks+" additive categories and exact swipeable chart accounting checks");
 }
}